fn median(xs:&[f64])->f64{let mut v=xs.to_vec();v.sort_by(f64::total_cmp);v[v.len()/2]}
fn rank(xs:&[f64])->Value{assert_eq!(xs.len(),31);let mut v=xs.to_vec();assert!(v.iter().all(|v|v.is_finite()&&*v>0.));v.sort_by(f64::total_cmp);json!({"median":v[15],"low":v[9],"high":v[21],"wins":xs.iter().filter(|&&v|v<1.).count(),"ratios":xs,"nominal_coverage":0.9705506265163422})}
fn finish(){assert_eq!(read(r("runs/result.json"))["status"],"complete");let pins:BTreeMap<String,String>=serde_json::from_value(read(r("pins.json"))).unwrap();checkpins(&pins);let log=fs::read_to_string(r("runs/latency/stdout.log")).unwrap();let mut inputs=vec![];let mut rows=BTreeMap::<(String,usize),Vec<Value>>::new();let mut complete=None;for l in log.lines(){if let Some(s)=l.strip_prefix("INPUT "){inputs.push(serde_json::from_str::<Value>(s).unwrap());}if let Some(s)=l.strip_prefix("ROW "){let v:Value=serde_json::from_str(s).unwrap();assert_eq!(v["all_outputs_oracle_checked"],true);assert_eq!(v["calls"],8);rows.entry((v["context"].as_str().unwrap().into(),v["mode"].as_u64().unwrap()as usize)).or_default().push(v);}if let Some(s)=l.strip_prefix("COMPLETE "){complete=Some(serde_json::from_str::<Value>(s).unwrap());}}assert_eq!(inputs.len(),18);assert_eq!(rows.len(),54);let complete=complete.unwrap();assert_eq!(complete["timed_builders"],13392);assert_eq!(complete["priming_builders"],162);
let mut pairs=BTreeMap::new();let mut cells=BTreeMap::new();let mut checks=BTreeMap::new();for i in&inputs{let name=i["name"].as_str().unwrap();for(mode,label)in[(0,"original"),(1,"swiss"),(2,"candidate")]{let v=&rows[&(name.into(),mode)];assert_eq!(v.len(),31);for(b,v)in v.iter().enumerate(){assert_eq!(v["block"],b);}cells.insert(format!("{name}/{label}"),json!({"median_ms":median(&v.iter().map(|v|v["mean_ms"].as_f64().unwrap()).collect::<Vec<_>>()),"blocks":v}));}for(control,label)in[(0,"original"),(1,"swiss")]{let ratios=(0..31).map(|b|rows[&(name.into(),2)][b]["mean_ms"].as_f64().unwrap()/rows[&(name.into(),control)][b]["mean_ms"].as_f64().unwrap()).collect::<Vec<_>>();let p=rank(&ratios);if control==0{checks.insert(format!("{name}/candidate/{label}/nonregression"),p["high"].as_f64().unwrap()<=1.03);}if name=="1x2/A"||name=="1x2/B"{checks.insert(format!("{name}/candidate/{label}/gain"),p["high"].as_f64().unwrap()<1.&&p["wins"].as_u64().unwrap()>=21);}pairs.insert(format!("{name}/candidate/{label}"),p);}}
let mut aggregates=BTreeMap::new();for label in["original","swiss"]{let p=rank(&(0..31).map(|b|(inputs.iter().map(|i|pairs[&format!("{}/candidate/{label}",i["name"].as_str().unwrap())]["ratios"][b].as_f64().unwrap().ln()).sum::<f64>()/18.).exp()).collect::<Vec<_>>());if label=="original"{checks.insert("all18/candidate/original/gain".into(),p["high"].as_f64().unwrap()<1.&&p["wins"].as_u64().unwrap()>=21);}aggregates.insert(label,p);}
let mut profiles=BTreeMap::new();for label in["original","swiss","candidate"]{let loss=read(r(format!("runs/loss-{label}/stdout.log")));assert_eq!(loss["zero_lost"],true);let ev=fs::read_to_string(r(format!("runs/events-{label}/stdout.log"))).unwrap();assert!(ev.contains("CPU")&&ev.contains("TIME")&&ev.contains("199"));let mut symbols=BTreeMap::<String,u64>::new();let mut pids=BTreeSet::new();let mut samples=0;for l in fs::read_to_string(r(format!("runs/decode-{label}/stdout.log"))).unwrap().lines().filter(|l|!l.trim().is_empty()&&!l.trim().starts_with('#')){let f:Vec<_>=l.split_whitespace().collect();pids.insert(f[0].split_once('/').unwrap().0.to_string());*symbols.entry(f[5..].join(" ")).or_default()+=f[3].parse::<u64>().unwrap();samples+=1;}assert_eq!(pids.len(),1);assert!(samples>0);profiles.insert(label,json!({"samples":samples,"PIDs":pids,"zero_lost":true,"symbol_periods":symbols,"raw_sha256":hash(r(format!("perf/{label}.data")))}));}
let failed:Vec<_>=checks.iter().filter(|(_,p)|!**p).map(|(k,_)|k.clone()).collect();let a=json!({"component_gate":failed.is_empty(),"complete":true,"checks":checks,"failed_checks":failed,"aggregates":aggregates,"pairs":pairs,"cells":cells,"inputs":inputs,"profiles":profiles,"capture_complete":complete,"native_tests":8,"SDK_requests":0,"new_proofs":0,"ledger":21259,"production_changed":false,"adopted":false,"source_pins_closed":pins.len(),"scope":"complete single-thread grouping constructors on real A/B scalar inputs, not proof latency"});save(r("analysis.json"),&a);println!("Gate{} failures{}",a["component_gate"],a["failed_checks"]);for(k,v)in&a["aggregates"].as_object().unwrap().iter().collect::<Vec<_>>(){println!("aggregate {k} {} [{},{}] wins{}",v["median"],v["low"],v["high"],v["wins"]);}for name in["1x2/A","1x2/B"]{for c in["original","swiss"]{let p=&a["pairs"][format!("{name}/candidate/{c}")];println!("{name}/{c} {} [{},{}] wins{}",p["median"],p["low"],p["high"],p["wins"]);}}}
